-- Demo portfolio reset: wipes the project data and ingests the demo portfolio again, so every workshop starts from the same
-- state. Plain data statements only, run by the platform owner (Zyad) in the Supabase dashboard, SQL Editor, in one go,
-- or by Claude Code through the Supabase MCP as a data fix when that session may run DELETE statements. Nothing in the app
-- can run it. One transaction: an error leaves the database as it was. Generated on 9 Oct 2026 from the seed migrations 20261009142725 and 20261009143326; the ids,
-- names and figures are the demo's own. Documented in docs/demo-portfolio.md.
--
-- What it keeps: every login identity (Supabase Auth), every profile that has a login (the three named people and any
-- workshop participant added on the Users screen), the sites and targets (values put back to the demo's), the settings.
-- What it wipes: every project, decision, history row and reference figure, the demo profiles' edits, test users without a login.
begin;

-- 1. wipe the record tables, children first
delete from public.decisions;
delete from public.project_history;
delete from public.reference_figures_history;
delete from public.reference_figures;
delete from public.projects;

-- 2. people: the ten demo profiles back as seeded (a login that exists is untouched); other profiles without a login are removed
on conflict (id) do update set email = excluded.email, name = excluded.name, role = excluded.role, site_id = excluded.site_id,
  retired_at = excluded.retired_at, retired_comment = excluded.retired_comment, created_at = excluded.created_at,
  updated_by = excluded.updated_by, updated_at = excluded.updated_at;

delete from public.profiles where auth_user_id is null and id not in ('67768eec-9c36-4f87-8868-f1edb7f14474', '643de8b6-386c-43a9-9c9a-40cf0ddb1501', '9d84c79b-e958-4922-bfd8-1e2781283aaa', 'e10eb550-21fc-58c5-82ed-d7abd6a4d03d', 'caa6b15f-230c-53dd-84ac-625267e300b0', 'e5c37ab3-e5ba-5720-b85f-350e2129ffa8', '4c64907b-ad32-55dd-88aa-479fefcc9154', '1dd238dd-1e6d-5e42-a7ac-6d1885f84046', 'c833cbec-fe77-5650-9673-cc9be2fbf2ad', '7d4eb238-4ce7-5cea-8a37-992881714c45');

-- 3. sites and targets back to the demo's values; a site added since is deactivated, never deleted
update public.sites set name = 'Werk Bielefeld', city = 'Bielefeld', type = 'Beverages plant', active = true, updated_by = null where id = '9c01d907-f9e2-4a4d-812c-eca747e88bab';
update public.sites set name = 'Logistikzentrum Bad Oeynhausen', city = 'Bad Oeynhausen', type = 'Logistics centre', active = true, updated_by = null where id = '9d255bbf-b1ae-4e47-aaec-e0b10f0245d9';
update public.sites set name = 'Werk Paderborn', city = 'Paderborn', type = 'Confectionery plant', active = true, updated_by = null where id = 'cf975afd-11d6-40b8-8211-a2e91aebbdb5';
update public.sites set name = 'Werk Gütersloh', city = 'Gütersloh', type = 'Food ingredients plant', active = true, updated_by = null where id = '6d279639-53c2-4c24-accb-6da269a4b39a';
update public.sites set name = 'Werk Minden', city = 'Minden', type = 'Home and personal care plant', active = true, updated_by = null where id = '543b5219-53bb-4282-9383-a030b22e84ea';
update public.sites set name = 'Werk Herford', city = 'Herford', type = 'Packaging plant', active = true, updated_by = null where id = '8fc0f53c-438c-44ce-9cd5-721ce505e3db';
update public.sites set name = 'Werk Lippstadt', city = 'Lippstadt', type = 'Homeware plant', active = true, updated_by = null where id = '2f0b22dc-5700-4e3c-a2a8-834c9507cd8e';
update public.sites set active = false where id not in ('9c01d907-f9e2-4a4d-812c-eca747e88bab', '9d255bbf-b1ae-4e47-aaec-e0b10f0245d9', 'cf975afd-11d6-40b8-8211-a2e91aebbdb5', '6d279639-53c2-4c24-accb-6da269a4b39a', '543b5219-53bb-4282-9383-a030b22e84ea', '8fc0f53c-438c-44ce-9cd5-721ce505e3db', '2f0b22dc-5700-4e3c-a2a8-834c9507cd8e');
update public.targets set value = 42, base_year = 2024, target_year = 2030, active = true, change_comment = null, set_by = null, updated_by = null where id = 'dc56e1a1-350d-41da-b1ab-5747f8833e0c';
update public.targets set value = 10, base_year = 2024, target_year = 2030, active = true, change_comment = null, set_by = null, updated_by = null where id = '0a83aabb-0f71-4d2f-b109-6ac29ec90e10';
update public.targets set value = 20, base_year = 2024, target_year = 2030, active = true, change_comment = null, set_by = null, updated_by = null where id = '439b8196-032e-46fa-9ab6-b619b821fdb4';
update public.targets set value = 95, base_year = 2024, target_year = 2030, active = true, change_comment = null, set_by = null, updated_by = null where id = '8ac1ae33-1e85-47d8-8731-d0b07842ba17';

-- 4. reference figures (the history trigger writes a 'created' row per figure; the demo has no figure history, so those rows go)

delete from public.reference_figures_history;

-- 5. projects, version 1 rows before version 2 (the history trigger's 'created' rows are replaced by the demo's own history below)

delete from public.project_history;

-- 6. decisions (written here directly; from now on only the transition functions write them)


-- 7. the demo's audit trail

-- 8. project codes continue at PRJ-0038
select setval('public.project_code_seq', 37, true);
commit;

-- 9. what the database holds now (the SQL Editor shows this row)
select (select count(*) from public.profiles) as profiles, (select count(*) from public.profiles where auth_user_id is not null) as profiles_with_login,
  (select count(*) from public.reference_figures) as reference_figures, (select count(*) from public.projects) as projects,
  (select count(*) from public.decisions) as decisions, (select count(*) from public.project_history) as project_history,
  'PRJ-' || lpad(((select last_value from public.project_code_seq) + 1)::text, 4, '0') as next_project_code;
